WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/50.0/connection.js")}
var records =  {!GETRECORDIDS( $ObjectType.Task)};
var returnURL = window.location.href;
if(records != null && records != ''){
     mywin = window.open('/apex/activities__CreateTasks?Ids='+records+'&retURL='+returnURL , '_top',
                                             'height=400,width=600,status=yes,toolbar=no,menubar=no,location=no,center=yes,resizable=no');
     mywin.focus();
}
}
